SELECT 'contracts_by_award_state' test,jsonb_agg(x) data FROM (SELECT aw.state,count(distinct ct.contract_id) contracts,sum(ct.closing_value)::text total FROM marts.contract_transactions ct JOIN core.awards aw ON aw.ca_notice_id=ct.ca_notice_id GROUP BY 1) x
UNION ALL SELECT 'invalid_dates',jsonb_agg(x) FROM (SELECT c.ca_notice_contract_id,c.contract_no,c.contract_date,aw.state_date,c.contract_value::text,c.title,c.raw_id FROM core.contracts c JOIN core.awards aw USING(ca_notice_id) WHERE c.contract_date<'2010-01-01' ORDER BY c.contract_date LIMIT 12) x
UNION ALL SELECT 'allocation_value_filter',to_jsonb(x) FROM (SELECT count(*) contracts_all_shares_under_million,sum(full_value)::text full_value FROM (SELECT contract_id,max(contract_value_full) full_value,max(closing_value) max_share FROM marts.contract_transactions GROUP BY 1 HAVING max(contract_value_full)>=1000000 AND max(closing_value)<1000000) z) x
UNION ALL SELECT 'network_roles',jsonb_agg(x) FROM (SELECT calitate,count(*) n FROM reference.company_reps WHERE birth_date IS NOT NULL GROUP BY 1 ORDER BY 2 DESC LIMIT 10) x
